// Fetches real vote totals from Supabase and merges them on top of the
// simulated baseline so the bars never start at 0.
async function loadVoteCounts() {
  if (!supabaseClient) return;
  try {
    const { data, error } = await supabaseClient
      .from('votes')
      .select('question_id, choice');
    if (error) throw error;
    // Reset to sim baseline, then increment from real data
    voteQs.forEach((q, i) => { voteCounts[i] = q.sim.slice(); });
    data.forEach(({ question_id, choice }) => {
      if (voteCounts[question_id]?.[choice] !== undefined) {
        voteCounts[question_id][choice]++;
      }
    });
    renderVotes();
  } catch(e) { console.warn('Could not load vote counts from Supabase:', e); }
}
function initRealtime(){
  if(!supabaseClient)return;

  // ── Live vote counts: update bars for every connected client on each INSERT ──
  supabaseClient
    .channel('public:votes')
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'votes'},(payload)=>{
      const qi=payload.new.question_id;
      const ch=payload.new.choice;
      if(voteCounts[qi]!==undefined&&voteCounts[qi][ch]!==undefined){
        voteCounts[qi][ch]++;
        // Only re-render the bar row if this question's bars are already visible
        const bars=document.getElementById('bars-'+qi);
        if(bars&&bars.classList.contains('show')){
          // Capture current displayed % so we animate from there, not from 0
          const fromPct=[...bars.querySelectorAll('.bar-fill')].map(el=>parseFloat(el.style.width)||0);
          bars.innerHTML=buildBars(voteQs[qi],voteCounts[qi]);
          animateBars(bars,fromPct);
        }
      }
    })
    .subscribe();

  // ── Live leaderboard: reload on every INSERT or DELETE ──
  supabaseClient
    .channel('public:leaderboard')
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'leaderboard'},()=>{
      const lb=document.getElementById('leaderboard-section');
      if(lb&&lb.style.display!=='none')loadLeaderboard();
    })
    .on('postgres_changes',{event:'DELETE',schema:'public',table:'leaderboard'},()=>{
      const lb=document.getElementById('leaderboard-section');
      if(lb&&lb.style.display!=='none')loadLeaderboard();
    })
    .subscribe();

  // ── Presence: show how many people are viewing Section 02 right now ──
  const uid=Math.random().toString(36).slice(2);
  const presenceCh=supabaseClient.channel('presence:site');
  presenceCh
    .on('presence',{event:'sync'},()=>{
      const n=Object.keys(presenceCh.presenceState()).length;
      const el=document.getElementById('live-count');
      if(el)el.textContent=n+(n===1?' person online':' people online');
    })
    .subscribe(async(status)=>{
      if(status==='SUBSCRIBED')await presenceCh.track({uid,joined:Date.now()});
    });
}
