function saveName(){
  const input=document.getElementById('name-input');
  if(!input)return;
  const n=input.value.trim().replace(/[<>]/g,'').slice(0,20);
  if(!n)return;
  playerName=n;
  localStorage.setItem('guestName',n);
  renderGuess();
}

function lockSlider(){
  if(gRevealed)return; gRevealed=true;
  const q=guessQs[gIdx];
  const v=parseInt(document.getElementById('g-slider').value);
  document.getElementById('g-slider').disabled=true;
  const diff=Math.abs(v-q.answer);
  const pctOff=q.answer!==0?diff/q.answer:diff;
  let cls,lbl;
  if(pctOff<0.08){cls='correct';lbl='Spot on!';}
  else if(pctOff<0.25){cls='close';lbl='Pretty close!';}
  else{cls='wrong';lbl='Not quite —';}
  gScores[gIdx]=cls==='correct'?100:cls==='close'?50:10;
  if(cls==='correct')triggerConfetti();
  const box=document.getElementById('g-reveal');
  box.className='reveal-box '+cls+' show';
  box.innerHTML=`<div class="reveal-num">${q.answer} ${q.unit}</div><div class="reveal-text">${lbl} ${q.hint}</div><div class="reveal-source">Source: ${q.source}</div>`;
  showNextBtn();
}

function initScratch(){
  const canvas=document.getElementById('scratch-canvas');
  if(!canvas)return;
  scratchRevealed=false;
  const num=document.getElementById('sc-num');
  const sub=document.getElementById('sc-sub');
  if(num) num.style.opacity='0';
  if(sub) sub.style.opacity='0';
  canvas.style.opacity='1';
  const W=canvas.offsetWidth*2;
  const H=240;
  canvas.width=W; canvas.height=H;
  scratchCtx=canvas.getContext('2d');
  scratchCtx.fillStyle='#334155';
  scratchCtx.fillRect(0,0,W,H);
  scratchCtx.fillStyle='#94A3B8';
  scratchCtx.font=`bold ${W*0.048}px sans-serif`;
  scratchCtx.textAlign='center';
  scratchCtx.fillText('Scratch here to reveal',W/2,H/2-8);
  scratchCtx.font=`${W*0.036}px sans-serif`;
  scratchCtx.fillStyle='#64748B';
  scratchCtx.fillText('the real answer',W/2,H/2+24);
  function doScratch(x,y){
    const rect=canvas.getBoundingClientRect();
    const sx=(x-rect.left)*(W/rect.width);
    const sy=(y-rect.top)*(H/rect.height);
    scratchCtx.globalCompositeOperation='destination-out';
    scratchCtx.beginPath();
    scratchCtx.arc(sx,sy,46,0,Math.PI*2);
    scratchCtx.fill();
    if(!scratchRevealed) checkScratch(canvas);
  }
  canvas.onmousedown=()=>isScratching=true;
  canvas.onmouseup=()=>isScratching=false;
  canvas.onmouseleave=()=>isScratching=false;
  canvas.onmousemove=e=>{if(isScratching)doScratch(e.clientX,e.clientY);};
  canvas.ontouchstart=e=>{isScratching=true;e.preventDefault();doScratch(e.touches[0].clientX,e.touches[0].clientY);};
  canvas.ontouchend=()=>isScratching=false;
  canvas.ontouchmove=e=>{e.preventDefault();if(isScratching)doScratch(e.touches[0].clientX,e.touches[0].clientY);};
}

function checkScratch(canvas){
  const d=scratchCtx.getImageData(0,0,canvas.width,canvas.height).data;
  let t=0;
  for(let i=3;i<d.length;i+=4){if(d[i]<128)t++;}
  if(t/(canvas.width*canvas.height)>0.42){
    scratchRevealed=true;
    canvas.style.transition='opacity 0.5s';
    canvas.style.opacity='0';
    const num=document.getElementById('sc-num');
    const sub=document.getElementById('sc-sub');
    if(num) num.style.opacity='1';
    if(sub) sub.style.opacity='1';
    const q=guessQs[gIdx];
    document.getElementById('sc-hint').textContent='Source: '+q.source;
    const box=document.getElementById('g-reveal');
    if(box){box.className='reveal-box correct show';box.innerHTML=`<div class="reveal-text">${q.hint}</div>`;}
    if(!gRevealed){gRevealed=true;gScores[gIdx]=50;showNextBtn();}
  }
}

function tapAnswer(btn,correct,correctIdx){
  if(gRevealed)return; gRevealed=true;
  document.querySelectorAll('#tap-grid .tap-btn').forEach((b,i)=>{
    b.classList.add('disabled');
    if(i===correctIdx) b.classList.add('reveal-it');
  });
  btn.classList.remove('reveal-it');
  btn.classList.add(correct?'correct':'wrong');
  const q=guessQs[gIdx];
  const box=document.getElementById('g-reveal');
  gScores[gIdx]=correct?100:10;
  if(correct)triggerConfetti();
  box.className='reveal-box '+(correct?'correct':'wrong')+' show';
  box.innerHTML=`<div class="reveal-num">${q.opts[q.answerIdx]}</div><div class="reveal-text">${correct?'Correct! ':'Wrong. '}${q.hint}</div><div class="reveal-source">Source: ${q.source}</div>`;
  showNextBtn();
}

function onDragStart(e){draggedItem=e.currentTarget;e.dataTransfer.effectAllowed='move';}
function onDragOver(e){e.preventDefault();e.currentTarget.classList.add('over');}
function onDragLeave(e){e.currentTarget.classList.remove('over');}
function onDrop(e,zone){
  e.preventDefault();
  e.currentTarget.classList.remove('over');
  if(!draggedItem)return;
  const correct=draggedItem.dataset.cat===zone;
  if(correct)gDragScore+=15;
  const d=document.createElement('div');
  d.className='dropped '+(correct?'right':'wrong-d');
  d.textContent=draggedItem.textContent.trim();
  e.currentTarget.appendChild(d);
  draggedItem.classList.add('used');
  draggedItem=null;
  const pool=document.getElementById('drag-pool');
  if(pool&&pool.querySelectorAll('.drag-item:not(.used)').length===0){
    gScores[gIdx]=gDragScore;
    document.getElementById('drag-msg').textContent='All sorted! Green = correct, red = wrong placement.';
    if(!gRevealed){gRevealed=true;showNextBtn();}
  }
}
function onTouchStart(e){
  touchDragItem=e.currentTarget;
  const t=e.touches[0];
  touchClone=touchDragItem.cloneNode(true);
  touchClone.style.cssText='position:fixed;pointer-events:none;opacity:0.88;z-index:999;width:'+touchDragItem.offsetWidth+'px;left:'+(t.clientX-touchDragItem.offsetWidth/2)+'px;top:'+(t.clientY-20)+'px;background:#334155;border:1px solid #60A5FA;border-radius:10px;padding:10px 12px;font-size:13px;color:#F1F5F9;display:flex;align-items:center;gap:8px;';
  document.body.appendChild(touchClone);
}
function onTouchMove(e){
  e.preventDefault();
  if(!touchClone)return;
  const t=e.touches[0];
  touchClone.style.left=(t.clientX-touchClone.offsetWidth/2)+'px';
  touchClone.style.top=(t.clientY-20)+'px';
}
function onTouchEnd(e){
  if(touchClone){document.body.removeChild(touchClone);touchClone=null;}
  if(!touchDragItem)return;
  const t=e.changedTouches[0];
  const el=document.elementFromPoint(t.clientX,t.clientY);
  const zone=el&&el.closest('#drop-then,#drop-now');
  if(zone){
    const zoneId=zone.id.replace('drop-','');
    draggedItem=touchDragItem;
    onDrop({preventDefault:()=>{},currentTarget:zone},zoneId);
  }
  touchDragItem=null;
}

function showNextBtn(){
  const nb=document.getElementById('g-next-btn');
  if(!nb)return;
  nb.style.display='flex';
  if(gIdx<guessQs.length-1){
    nb.onclick=nextGuess;
    nb.innerHTML='Next <i class="ti ti-arrow-right" aria-hidden="true"></i>';
  }else{
    nb.onclick=finishGuess;
    nb.innerHTML='See my score <i class="ti ti-trophy" aria-hidden="true"></i>';
  }
}
function nextGuess(){
  if(gIdx<guessQs.length-1){gIdx++;renderGuess();}
}

async function finishGuess(){
  const total=gScores.reduce((a,b)=>a+(b||0),0);
  // Reveal leaderboard card
  const lb=document.getElementById('leaderboard-section');
  if(lb){
    lb.style.display='block';
    document.getElementById('lb-total').textContent=total;
    // Breakdown line: Q1:100 · Q2:50 · …
    const medals=['🥇','🥈','🥉'];
    const breakdown=gScores.map((s,i)=>{
      const q=guessQs[i];
      const label=q.type==='drag'?'Drag':q.type==='scratch'?'Scratch':q.type==='tap'?'Tap':'Slider';
      return`<span class="score-chip ${s>=100?'chip-gold':s>=50?'chip-silver':'chip-bronze'}">${label}: ${s||0}</span>`;
    }).join('');
    document.getElementById('lb-breakdown').innerHTML=breakdown;
    setTimeout(()=>lb.scrollIntoView({behavior:'smooth',block:'start'}),80);
  }
  // Save score to Supabase leaderboard (rate-limited)
  if(supabaseClient&&playerName){
    const scoreAllowed=await checkRateLimit('leaderboard');
    if(!scoreAllowed){
      showToast('Score already submitted — leaderboard not updated.','warn');
    } else {
      try{
        console.log('[Leaderboard] Saving:', playerName, total+'pts');
        const{data,error}=await supabaseClient
          .from('leaderboard').insert({name:playerName,score:total}).select('id');
        if(error){
          console.error('[Leaderboard] Insert failed:', error.message, error);
        } else if(data&&data[0]){
          myLeaderboardId=data[0].id;
          console.log('[Leaderboard] Saved — id:', myLeaderboardId);
        }
      }catch(e){console.error('[Leaderboard] Insert threw:', e);}
    }
  } else {
    console.log('[Leaderboard] Skipped — supabase:', !!supabaseClient, '| name:', JSON.stringify(playerName));
  }
  loadLeaderboard();
}

async function loadLeaderboard(){
  if(!supabaseClient)return;
  try{
    const{data}=await supabaseClient
      .from('leaderboard').select('id,name,score')
      .order('score',{ascending:false}).limit(10);
    renderLeaderboard(data||[]);
  }catch(e){console.warn('Leaderboard fetch failed:',e);}
}

function renderLeaderboard(rows){
  const el=document.getElementById('lb-rows');
  if(!el)return;
  if(!rows.length){
    el.innerHTML='<div class="lb-empty">No scores yet — be the first!</div>';
    return;
  }
  const medals=['🥇','🥈','🥉'];
  el.innerHTML=rows.map((r,i)=>{
    const isMe=r.id!==null&&r.id===myLeaderboardId;
    return`<div class="lb-row${isMe?' lb-me':''}">
      <span class="lb-rank">${medals[i]||'#'+(i+1)}</span>
      <span class="lb-name">${r.name}${isMe?' <span class="lb-you">you</span>':''}</span>
      <span class="lb-score">${r.score}<span class="lb-pts">pts</span></span>
    </div>`;
  }).join('');
}

async function adminReset(){
  const pw=prompt('Admin password:');
  if(!pw)return;
  if(!supabaseClient){alert('Supabase not connected.');return;}
  try{
    const{error}=await supabaseClient.rpc('reset_leaderboard',{admin_pass:pw});
    if(error)throw error;
    myLeaderboardId=null;
    loadLeaderboard();
  }catch(e){alert('Reset failed: '+(e.message||'Wrong password'));}
}

function renderVotes(){
  const c=document.getElementById('vote-container');
  c.innerHTML='';
  voteQs.forEach((q,i)=>{
    if(!voteCounts[i])voteCounts[i]=q.sim.slice();
    const div=document.createElement('div');
    div.className='vote-q'+(voteAnswered[i]!==undefined?' answered':'');
    div.id='vq-'+i;
    let btns='';
    const answered=voteAnswered[i]!==undefined;
    if(q.type==='yn'){
      btns=`<div class="vote-grid">${q.labels.map((l,j)=>`<button class="vote-btn ${j===0?'yes':'no'}${voteAnswered[i]===j?' picked':''}" onclick="castVote(${i},${j})"${answered?' disabled':''}>${l}</button>`).join('')}</div>`;
    } else {
      btns=`<div class="vote-grid">${q.opts.map((o,j)=>`<button class="vote-btn opt${voteAnswered[i]===j?' picked':''}" onclick="castVote(${i},${j})"${answered?' disabled':''}>${o}</button>`).join('')}</div>`;
    }
    div.innerHTML=`<img src="${IMGS[voteImgs[i]]}" class="scene-img" alt="" aria-hidden="true"><div class="vote-body"><div class="q-label">Question ${i+1} of ${voteQs.length}</div><div style="font-size:15px;font-weight:600;color:#F1F5F9;margin-bottom:0.75rem;line-height:1.4">${q.q}</div>${btns}<div class="result-bars${voteAnswered[i]!==undefined?' show':''}" id="bars-${i}">${voteAnswered[i]!==undefined?buildBars(q,voteCounts[i]):''}</div></div>`;
    c.appendChild(div);
    // Animate bars for questions already answered (restored from localStorage)
    if(voteAnswered[i]!==undefined){
      const barsEl=div.querySelector('#bars-'+i);
      if(barsEl) animateBars(barsEl);
    }
  });
}

async function castVote(qi,choice){
  if(voteAnswered[qi]!==undefined)return;

  // Guard 1 — client-side 24 h timestamp check
  // Persists independently of voteAnswered so re-voting is blocked even if
  // the user clears voteAnswered from localStorage.
  const tsKey='vt_'+qi;
  const lastVote=parseInt(localStorage.getItem(tsKey)||'0');
  if(lastVote&&Date.now()-lastVote<864e5){  // 864e5 ms = 24 hours
    showToast('You already voted on this question');
    return;
  }

  // Guard 2 — server-side rate limit (max 3 per question per user per hour)
  const voteAllowed=await checkRateLimit('vote_q'+qi);
  if(!voteAllowed){
    showToast('Too many attempts — please wait before voting again.','warn');
    return;
  }

  // 1. Lock in answer + persist across reloads (store 24 h timestamp too)
  voteAnswered[qi]=choice;
  try{localStorage.setItem('va',JSON.stringify(voteAnswered));}catch(e){}
  try{localStorage.setItem(tsKey,String(Date.now()));}catch(e){}

  // 2. Immediate visual feedback: mark picked button, disable all buttons for this question
  const vq=document.getElementById('vq-'+qi);
  if(vq){
    vq.classList.add('answered');
    vq.querySelectorAll('.vote-btn').forEach((b,j)=>{
      b.classList.remove('picked');
      if(j===choice)b.classList.add('picked');
      b.disabled=true;
    });
    // Show bars instantly with current counts; Realtime will tick them up ~100 ms later
    const bars=document.getElementById('bars-'+qi);
    if(bars){bars.innerHTML=buildBars(voteQs[qi],voteCounts[qi]);bars.classList.add('show');animateBars(bars);}
  }
  if(Object.keys(voteAnswered).length===voteQs.length)
    document.getElementById('vote-done').classList.add('show');

  // 3. Send to Supabase — the Realtime subscription handles updating counts for everyone
  if(supabaseClient){
    try{await supabaseClient.from('votes').insert({question_id:qi,choice});}
    catch(e){
      console.warn('Vote insert failed, falling back to local count:',e);
      // Offline fallback: count locally so bars still animate
      voteCounts[qi][choice]++;
      const bars=document.getElementById('bars-'+qi);
      if(bars){const fp=[...bars.querySelectorAll('.bar-fill')].map(el=>parseFloat(el.style.width)||0);bars.innerHTML=buildBars(voteQs[qi],voteCounts[qi]);animateBars(bars,fp);}
    }
  }else{
    // No Supabase configured: count locally
    voteCounts[qi][choice]++;
    const bars=document.getElementById('bars-'+qi);
    if(bars){const fp=[...bars.querySelectorAll('.bar-fill')].map(el=>parseFloat(el.style.width)||0);bars.innerHTML=buildBars(voteQs[qi],voteCounts[qi]);animateBars(bars,fp);}
  }
}
// Animates bar widths and percentage numbers from fromPct[] → data-target over 600 ms.
// Pass fromPct to animate from a non-zero starting point (Realtime updates).
// Omit / pass undefined to animate from 0 (first appearance).
function animateBars(container, fromPct) {
  const DURATION = 600;
  const fills = [...container.querySelectorAll('.bar-fill[data-target]')];
  const pcts  = [...container.querySelectorAll('.bar-pct[data-target]')];
  if (!fills.length) return;

  // Ease-out cubic: fast start, gentle finish
  const ease = t => 1 - Math.pow(1 - t, 3);

  const from = fills.map((_, i) => fromPct ? (fromPct[i] ?? 0) : 0);
  const start = performance.now();

  function tick(now) {
    const t = Math.min((now - start) / DURATION, 1);
    const e = ease(t);
    fills.forEach((el, i) => {
      const end = +el.dataset.target;
      el.style.width = ((from[i] + (end - from[i]) * e)).toFixed(2) + '%';
    });
    pcts.forEach((el, i) => {
      const end = +el.dataset.target;
      el.textContent = Math.round(from[i] + (end - from[i]) * e) + '%';
    });
    if (t < 1) requestAnimationFrame(tick);
  }
  requestAnimationFrame(tick);
}

function buildBars(q,counts){
  const total=counts.reduce((a,b)=>a+b,0);
  const labels=q.type==='yn'?q.labels:q.opts;
  const fills=['fill-yes','fill-no','fill-opt','fill-opt'];
  return labels.map((lbl,j)=>{
    const p=total>0?Math.round((counts[j]/total)*100):0;
    // width starts at 0% — animateBars() drives it to data-target
    return `<div class="bar-row"><div class="bar-lbl"><span>${lbl}</span><span class="bar-pct" data-target="${p}">0%</span></div><div class="bar-track"><div class="bar-fill ${fills[j]}" style="width:0%" data-target="${p}"></div></div></div>`;
  }).join('');
}

function renderQuizSteps(){
  document.getElementById('quiz-steps').innerHTML=quizQs.map((_,i)=>(i>0?'<div class="step-line"></div>':'')+'<div class="step-dot'+(i<qIdx?' done':i===qIdx?' active':'')+'" id="sd-'+i+'"></div>').join('');
}
function renderQuiz(){
  document.getElementById('quiz-result').style.display='none';
  renderQuizSteps();
  const q=quizQs[qIdx];
  document.getElementById('quiz-container').innerHTML=`<div class="card glow-amber">
    <img src="${IMGS[quizImgs[qIdx]]}" class="scene-img" alt="" aria-hidden="true">
    <div class="card-body">
      <div class="q-label">Question ${qIdx+1} of ${quizQs.length}</div>
      <div class="q-text">${q.q}</div>
      <div id="opts-wrap">${q.opts.map((o,i)=>`<button class="quiz-opt${qAnswers[qIdx]===i?' selected':''}" onclick="pickQuiz(${i},this)">${o}</button>`).join('')}</div>
      <div class="nav-row" id="q-nav" style="${qAnswers[qIdx]!==undefined?'':'display:none'}">
        ${qIdx>0?'<button class="btn btn-sm" onclick="prevQuiz()"><i class="ti ti-arrow-left" aria-hidden="true"></i> Back</button>':''}
        <button class="btn btn-blue btn-sm" onclick="nextQuiz()" style="margin-left:auto">${qIdx===quizQs.length-1?'See my result <i class="ti ti-arrow-right" aria-hidden="true"></i>':'Next <i class="ti ti-arrow-right" aria-hidden="true"></i>'}</button>
      </div>
    </div>
  </div>`;
  pickedOpt=qAnswers[qIdx]!==undefined?qAnswers[qIdx]:null;
}
function pickQuiz(i,btn){
  document.querySelectorAll('.quiz-opt').forEach(b=>b.classList.remove('selected'));
  btn.classList.add('selected');
  pickedOpt=i;
  document.getElementById('q-nav').style.display='flex';
}
function nextQuiz(){
  if(pickedOpt===null)return;
  qAnswers[qIdx]=pickedOpt;
  if(qIdx<quizQs.length-1){qIdx++;pickedOpt=null;renderQuiz();}
  else showResult();
}
function prevQuiz(){if(qIdx>0){qIdx--;renderQuiz();}}
function showResult(){
  document.getElementById('quiz-container').innerHTML='';
  const a=qAnswers;

  // Determine result — ordered most-specific first; else always catches everything
  let r;
  if(a[1]===3 && a[4]===3 && a[6]>=2)                        r=results[0]; // Freethinker
  else if((a[1]===0||a[1]===1) && a[4]===0 && a[6]===0)      r=results[1]; // Classic
  else if(a[4]===1 || a[1]===2)                               r=results[2]; // Rebel
  else                                                         r=results[3]; // Unaware

  // Save quiz result to Supabase — rate-limited, fire-and-forget (never blocks UI).
  const resultKey = r.title.replace(/^The /, '');
  if(supabaseClient){
    checkRateLimit('quiz_result').then(allowed => {
      if(!allowed){ console.log('[Quiz] Rate limited — result not saved'); return; }
      supabaseClient.from('quiz_results')
        .insert({result_type: resultKey})
        .then(({error}) => {
          if(error) console.error('[Quiz] Save failed:', error.message, error);
          else      console.log('[Quiz] Result saved:', resultKey);
        }, e => console.error('[Quiz] Insert threw:', e));
    });
  }

  // Render result card
  const rc=document.getElementById('quiz-result');
  rc.style.display='block';
  rc.innerHTML=`<div class="result-card">
    <img src="${IMGS[r.imgKey]}" class="scene-img" alt="" aria-hidden="true">
    <div class="result-card-body">
      <div class="result-icon"><i class="ti ${r.icon}" aria-hidden="true"></i></div>
      <div class="result-title">${r.title}</div>
      <div class="result-desc">${r.desc}</div>
      <div class="result-traits">${r.traits.map(t=>`<span class="trait">${t}</span>`).join('')}</div>
      <button class="btn btn-sm" onclick="resetQuiz()"><i class="ti ti-refresh" aria-hidden="true"></i> Try again</button>
    </div>
  </div>`;
  // Scroll the result into view so it's always visible on small screens
  rc.scrollIntoView({behavior:'smooth', block:'start'});
  for(let i=0;i<quizQs.length;i++){const d=document.getElementById('sd-'+i);if(d)d.className='step-dot done';}
}
function resetQuiz(){qIdx=0;qAnswers=[];pickedOpt=null;renderQuizSteps();renderQuiz();document.getElementById('quiz-result').style.display='none';}

renderGuess();
renderVotes();
renderQuizSteps();
renderQuiz();
// Load real counts first, then open the Realtime channel so we never
// miss a vote that arrives between the initial fetch and the subscription.
loadVoteCounts().then(initRealtime);
